void modified()
{
    next modified();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        PurchLine purchLine = element.purchLine;
        if (purchLine.ItemBasePriceRecId != 0 && purchLine.PriceUnit != 1)
        {
            warning("@GlobalUnifiedPricing:PriceUnitChangingWarning");
        }
    }
}
